"""End-to-end check: random types/values -> KTEST -> recovered certificate."""
import base64, json, random, struct, sys
sys.path.insert(0, '/workspace/project/src')
sys.path.insert(0, '/workspace/tmp')
from eywa.offline import Campaign
from fuzz_layout import resolve_all, ref_layout, leaf_width

def ktest(objects):
    out = [b'KTEST', struct.pack('>I', 3), struct.pack('>I', 0),
           struct.pack('>II', 0, 0), struct.pack('>I', len(objects))]
    for name, data in objects:
        nb = name.encode()
        out.append(struct.pack('>I', len(nb)) + nb)
        out.append(struct.pack('>I', len(data)) + data)
    return base64.b64encode(b''.join(out)).decode()

def make_decl(rng, names, depth):
    kind = rng.choice(['bool', 'char', 'int', 'string', 'enum', 'array', 'struct',
                       'alias', 'alias'])
    if depth <= 0 and kind in ('array', 'struct'):
        kind = rng.choice(['bool', 'int', 'enum', 'string'])
    d = {'kind': kind}
    if kind == 'int': d['bits'] = rng.choice([1, 3, 8, 12, 16, 24, 32, 48, 64])
    if kind == 'string': d['maxsize'] = rng.randint(0, 4)
    if kind == 'enum': d['values'] = ['v%d' % i for i in range(rng.randint(1, 3))]
    if kind == 'array':
        d['element'] = rng.choice(names)
        d['size'] = rng.randint(0, 3)
    if kind == 'struct':
        d['fields'] = [['f%d' % i, rng.choice(names)] for i in range(rng.randint(0, 3))]
    if kind == 'alias':
        d['target'] = rng.choice(names)
    return d

def random_value(rng, resolved, name):
    node = resolved[name]
    kind = node[0]
    while kind == 'alias':
        node = node[2]
        kind = node[0]
    if kind == 'bool': return rng.random() < 0.5
    if kind == 'char': return chr(rng.choice([0, 65, 200, 255]))
    if kind == 'int': return rng.randint(0, (1 << node[2]['bits']) - 1)
    if kind == 'enum': return rng.choice(node[2]['values'])
    if kind == 'string':
        size = node[2]['maxsize']
        chars = []
        nulled = rng.random() < 0.5
        for i in range(size):
            if nulled and i == rng.randrange(max(1, size)):
                chars.append('\x00')
            else:
                chars.append(rng.choice(['a', 'b', '\x00', '\xff']))
        return ''.join(chars)
    if kind == 'array':
        return [random_value(rng, resolved, node[2][1]) for _ in range(node[3])]
    if kind == 'struct':
        return {f: random_value(rng, resolved, t[1]) for f, t in node[2]}
    raise AssertionError(kind)

def encode_value(value, node, objects):
    kind = node[0]
    if kind == 'alias':
        return encode_value(value, node[2], objects)
    if kind == 'bool':
        return int(bool(value)).to_bytes(1, 'little')
    if kind == 'char':
        return ord(value).to_bytes(1, 'little')
    if kind == 'int':
        width = leaf_width('int', node[2])
        return value.to_bytes(width, 'little')
    if kind == 'enum':
        return node[2]['values'].index(value).to_bytes(4, 'little')
    if kind == 'string':
        chars = list(value.ljust(node[2]['maxsize'], '\x00'))[:node[2]['maxsize']]
        return [ord(c).to_bytes(1, 'little') for c in chars]
    if kind == 'array':
        return [encode_value(v, node[2], objects) for v in value]
    if kind == 'struct':
        out = {}
        for f, t in node[2]:
            out[f] = encode_value(value[f], t, objects)
        return out
    raise AssertionError(kind)

def flatten(parts, out):
    if isinstance(parts, list):
        for item in parts:
            flatten(item, out)
    else:
        out.append(parts)
    return out

rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
fails = 0
checked = 0
for trial in range(400):
    count = rng.randint(3, 8)
    names = ['T%d' % i for i in range(count)]
    decls = {}
    for i, name in enumerate(names):
        decls[name] = make_decl(rng, names[:i] or ['bool'], 3)
    resolved = resolve_all(decls)
    nparams = rng.randint(1, 3)
    param_types = [rng.choice(names) for _ in range(nparams)]
    result_type = rng.choice(names)
    params = [['p%d' % i, t] for i, t in enumerate(param_types)]
    intended = {pname: random_value(rng, resolved, ptype) for pname, ptype in params}
    result_value = random_value(rng, resolved, result_type)
    campaign = {
        'types': [dict({'name': k}, **v) for k, v in decls.items()],
        'modules': [{'name': 'app', 'params': params, 'result': ['out', result_type],
                     'requires': None}],
        'calls': [], 'pipes': [], 'entries': ['app'], 'machine': None, 'runs': []}
    cert = Campaign(campaign).certificate()
    plan = cert['plans'][0]
    slots, flag, variables, decls_out = ref_layout(resolved, params, result_type, False)
    if plan['slots'] != slots or plan['variables'] != variables:
        fails += 1
        print('LAYOUT MISMATCH', trial, plan['slots'], slots)
        break
    # encode the objects in a shuffled order
    by_path = {}
    for tag, path, _width in slots:
        by_path[tuple(path)] = tag
    leaf_parts = []
    for pname, ptype in params:
        leaf_parts.append((pname, encode_value(intended[pname], resolved[ptype], {})))
    if result_type != 'Void':
        leaf_parts.append(('out', encode_value(result_value, resolved[result_type], {})))
    objects = {}
    def assign(path, data):
        tag = by_path[tuple(path)]
        objects[tag] = data
    def walk(path, parts, node):
        kind = node[0]
        while kind == 'alias':
            node = node[2]; kind = node[0]
        if kind in ('bool', 'char', 'int', 'enum'):
            assign(path, parts)
            return
        if kind == 'string':
            for i, data in enumerate(parts):
                assign(path + [i], data)
            return
        if kind == 'array':
            for i, item in enumerate(parts):
                walk(path + [i], item, node[2])
            return
        if kind == 'struct':
            for (f, _t), item in zip(node[2], [parts[f] for f in node[2][0:0]] or [parts[f] for f, _t in node[2]]):
                walk(path + [f], item, dict(node[2]).get(f) or [t for ff, t in node[2] if ff == f][0])
            return
        raise AssertionError(kind)
    for pname, ptype in params:
        walk([pname], leaf_parts and None, None) if False else None
    # simpler: recursive emit driven by the reference layout slots
    def emit(path, value, node):
        kind = node[0]
        while kind == 'alias':
            node = node[2]; kind = node[0]
        if kind in ('bool', 'char', 'int', 'enum'):
            assign(path, encode_value(value, node, {}))
        elif kind == 'string':
            for i, c in enumerate(value.ljust(node[2]['maxsize'], '\x00')[:node[2]['maxsize']]):
                assign(path + [i], ord(c).to_bytes(1, 'little'))
        elif kind == 'array':
            for i, item in enumerate(value):
                emit(path + [i], item, node[2])
        elif kind == 'struct':
            for f, t in node[2]:
                emit(path + [f], value[f], t)
    for pname, ptype in params:
        emit([pname], intended[pname], resolved[ptype])
    if result_type != 'Void':
        emit(['out'], result_value, resolved[result_type])
    items = list(objects.items())
    rng.shuffle(items)
    campaign['runs'] = [{'entry': 'app', 'ktest': ktest(items)}]
    cert = Campaign(campaign).certificate()
    checked += 1
    record = cert['records'][0]
    if record['status'] != 'READY':
        print('RECORD', trial, record); fails += 1; break
    got = cert['corpus'][0]['inputs']
    want = dict(intended)
    if got != want:
        fails += 1
        print('VALUE MISMATCH', trial)
        print('  params', params)
        print('  got ', json.dumps(got, sort_keys=True))
        print('  want', json.dumps(want, sort_keys=True))
        if fails > 2: break
    if result_type != 'Void' and record['model_result'] != result_value:
        fails += 1
        print('RESULT MISMATCH', trial, record['model_result'], result_value)
        if fails > 2: break
print('value fuzz done, failures:', fails, 'checked:', checked)
PYEOF
